from datetime import datetime, timedelta

def parse(path):
    ev=[]; cur={}
    for line in open(path):
        line=line.strip()
        if line=='BEGIN:VEVENT': cur={}
        elif line=='END:VEVENT': ev.append(cur)
        elif ':' in line and cur is not None:
            k,v=line.split(':',1); cur[k.split(';')[0]]=v
    out=[]
    for e in ev:
        s=datetime.strptime(e['DTSTART'],'%Y%m%dT%H%M%SZ')
        t=datetime.strptime(e['DTEND'],'%Y%m%dT%H%M%SZ')
        out.append((s,t))
    return out

A=parse('/app/alice_calendar.ics'); B=parse('/app/bob_calendar.ics'); C=parse('/app/carol_calendar.ics')

def hard_windows(d):
    # day start 9:00; return list of allowed intervals for the person that day
    pass

def ok(person, s, e, day):
    wd=day.weekday()  # Mon=0
    # Alice: 9-14 hard
    if person=='A' and not (s.time()>=datetime.strptime('09:00','%H:%M').time() and e.time()<=datetime.strptime('14:00','%H:%M').time() and e.date()==s.date()): return False
    # Bob: >=10:00, Tue/Thu end <=16:30
    if person=='B':
        if s.time()<datetime.strptime('10:00','%H:%M').time(): return False
        if wd in (1,3) and e.time()>datetime.strptime('16:30','%H:%M').time(): return False
    # Carol: 9-17, lunch 12:00-12:30
    if person=='C':
        if s.time()<datetime.strptime('09:00','%H:%M').time() or e.time()>datetime.strptime('17:00','%H:%M').time(): return False
        lunch_s=datetime.combine(day,datetime.strptime('12:00','%H:%M').time())
        lunch_e=datetime.combine(day,datetime.strptime('12:30','%H:%M').time())
        if s<lunch_e and e>lunch_s: return False
    return True

cal={'A':A,'B':B,'C':C}
def free_of_conflicts(person,s,e):
    return all(not (s<t and e>st) for st,t in cal[person])

start_day=datetime(2024,1,15)
found=[]
for d in range(5):
    day=start_day+timedelta(days=d)
    cur=datetime.combine(day,datetime.strptime('09:00','%H:%M').time())
    end=datetime.combine(day,datetime.strptime('18:00','%H:%M').time())
    while cur+timedelta(hours=1)<=end:
        s=cur; e=cur+timedelta(hours=1)
        if all(ok(p,s,e,day) and free_of_conflicts(p,s,e) for p in 'ABC'):
            found.append((s,e,day.weekday()))
        cur+=timedelta(minutes=1)
print("Valid slots count:",len(found))
for f in found[:5]: print(f)
# check output
